 15→DotEnv.Load();
 16→
 17→var appSettings = AppSettings.FromEnvironment();
 18→
 19→var builder = WebApplication.CreateBuilder(args);
 20→
 21→builder.Services.AddSingleton(appSettings);
 22→builder.Services.AddOpenApi();
 23→
 24→// Database
 25→builder.Services.AddDbContext<AppDbContext>(options =>
 26→{
 27→    if (builder.Environment.IsDevelopment())
 28→        options.UseSqlite("Data Source=app.db");
 29→    else
 30→        options.UseNpgsql(appSettings.DatabaseUrl);
 31→});
 32→
 33→// CORS
 34→builder.Services.AddCors(options =>
 35→{
 36→    options.AddDefaultPolicy(policy =>
 37→    {
 38→        var origins = appSettings.CorsOrigins
 39→            .Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
 40→
 41→        policy.WithOrigins(origins)
 42→              .AllowAnyHeader()
 43→              .AllowAnyMethod()
 44→              .AllowCredentials();
 45→    });
 46→});
 47→
 48→// Authentication
 49→if (appSettings.AutoLogin && builder.Environment.IsDevelopment())
 50→{
 51→    builder.Services.AddAuthentication("DevAutoLogin")
 52→        .AddScheme<AuthenticationSchemeOptions, DevAutoLoginHandler>("DevAutoLogin", null);
 53→}
 54→else
 55→{
 56→    builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
 57→        .AddJwtBearer(options =>
 58→        {
 59→            options.Authority = appSettings.Authority;
 60→            options.Audience = appSettings.KeycloakClientId;
 61→            options.RequireHttpsMetadata = !builder.Environment.IsDevelopment();
 62→
 63→            options.TokenValidationParameters = new TokenValidationParameters
 64→            {
 65→                ValidateIssuer = true,
 66→                ValidIssuer = appSettings.Authority,
 67→                ValidateAudience = true,
 68→                ValidAudience = appSettings.KeycloakClientId,
 69→                ValidateLifetime = true,
 70→            };
 71→
 72→            options.Events = new JwtBearerEvents
 73→            {
 74→                OnTokenValidated = context =>
 75→                {
 76→                    if (context.Principal?.Identity is not ClaimsIdentity identity)
 77→                        return Task.CompletedTask;
 78→
 79→                    var realmAccess = identity.FindFirst("realm_access")?.Value;
 80→                    if (realmAccess is null)
 81→                        return Task.CompletedTask;
 82→
 83→                    try
 84→                    {
 85→                        using var doc = JsonDocument.Parse(realmAccess);
 86→                        if (doc.RootElement.TryGetProperty("roles", out var roles))
 87→                        {
 88→                            foreach (var role in roles.EnumerateArray())
 89→                            {
 90→                                var value = role.GetString();
 91→                                if (!string.IsNullOrEmpty(value))
 92→                                    identity.AddClaim(new Claim(ClaimTypes.Role, value));
 93→                            }
 94→                        }
 95→                    }
 96→                    catch (JsonException)
 97→                    {
 98→                        // Ignore malformed claim
 99→                    }
100→
101→                    return Task.CompletedTask;
102→                }
103→            };
104→        });
105→}
106→
107→builder.Services.AddAuthorization();
108→
109→var app = builder.Build();
110→
111→// Auto-apply migrations
112→using (var scope = app.Services.CreateScope())
113→{
114→    var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
115→    db.Database.Migrate();
116→}
117→
118→if (app.Environment.IsDevelopment())
119→{
120→    app.MapOpenApi();
121→    app.MapScalarApiReference("/docs");
122→}
123→
124→app.UseCors();
125→app.UseAuthentication();
126→app.UseAuthorization();
127→
128→app.UseStaticFiles(new StaticFileOptions
129→{
130→    FileProvider = new PhysicalFileProvider(
131→        Path.Combine(builder.Environment.ContentRootPath, ".frontend", "dist")),
132→    RequestPath = ""
133→});
134→
135→// Endpoints
136→
137→app.MapGet("/api/health", () => Results.Ok(new { Status = "Healthy" }))
138→    .Produces<object>(StatusCodes.Status200OK);
139→
140→app.MapGet("/api/me", (ClaimsPrincipal user) => Results.Ok(new
141→    {
142→        Sub = user.FindFirstValue(ClaimTypes.NameIdentifier) ?? user.FindFirstValue("sub"),
143→        PreferredUsername = user.FindFirstValue("preferred_username"),
144→        Email = user.FindFirstValue(ClaimTypes.Email) ?? user.FindFirstValue("email"),
145→        GivenName = user.FindFirstValue(ClaimTypes.GivenName) ?? user.FindFirstValue("given_name"),
146→        FamilyName = user.FindFirstValue(ClaimTypes.Surname) ?? user.FindFirstValue("family_name"),
147→        Roles = user.FindAll(ClaimTypes.Role).Select(c => c.Value).ToList(),
148→    }))
149→    .RequireAuthorization()
150→    .Produces<object>(StatusCodes.Status200OK)
151→    .Produces(StatusCodes.Status401Unauthorized);
152→
153→// SPA fallback
154→
155→app.MapFallback(async context =>
156→{
157→    if (context.Request.Path.StartsWithSegments("/api"))
158→    {
159→        context.Response.StatusCode = 404;
160→        await context.Response.WriteAsJsonAsync(new { Error = "Not Found" });
161→        return;
162→    }
163→
164→    var indexPath = Path.Combine(builder.Environment.ContentRootPath, ".frontend", "dist", "index.html");
165→    context.Response.ContentType = "text/html";
166→    await context.Response.SendFileAsync(indexPath);
167→});
168→
169→app.Run();
