171→// Dev-only auth handler: auto-authenticates every request with all roles
172→sealed class DevAutoLoginHandler(
173→    IOptionsMonitor<AuthenticationSchemeOptions> options,
174→    ILoggerFactory logger,
175→    UrlEncoder encoder)
176→    : AuthenticationHandler<AuthenticationSchemeOptions>(options, logger, encoder)
177→{
178→    protected override Task<AuthenticateResult> HandleAuthenticateAsync()
179→    {
180→        var claims = new List<Claim>
181→        {
182→            new(ClaimTypes.NameIdentifier, "dev-user-id"),
183→            new("sub", "dev-user-id"),
184→            new("preferred_username", "developer"),
185→            new(ClaimTypes.Email, "dev@localhost"),
186→            new("email", "dev@localhost"),
187→            new(ClaimTypes.GivenName, "Dev"),
188→            new("given_name", "Dev"),
189→            new(ClaimTypes.Surname, "User"),
190→            new("family_name", "User"),
191→            new(ClaimTypes.Role, "admin"),
192→            new(ClaimTypes.Role, "user"),
193→            new(ClaimTypes.Role, "student"),
194→            new(ClaimTypes.Role, "teacher"),
195→        };
196→
197→        var identity = new ClaimsIdentity(claims, Scheme.Name);
198→        var principal = new ClaimsPrincipal(identity);
199→        var ticket = new AuthenticationTicket(principal, Scheme.Name);
200→
201→        return Task.FromResult(AuthenticateResult.Success(ticket));
202→    }
203→}
