49→    private static void Validate(AppSettings settings)
50→    {
51→        var context = new ValidationContext(settings);
52→        var results = new List<ValidationResult>();
53→
54→        if (!Validator.TryValidateObject(settings, context, results, validateAllProperties: true))
55→        {
56→            var errors = string.Join(Environment.NewLine, results.Select(r => r.ErrorMessage));
57→            throw new InvalidOperationException(
58→                $"AppSettings validation failed:{Environment.NewLine}{errors}");
59→        }
60→    }
