using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using OmgtuPortal.University;

namespace OmgtuPortal.Controllers;

[ApiController]
[Route("api/[controller]")]
public class GroupsController(IUniversityClient universityClient) : ControllerBase
{
    [HttpGet]
    public async Task<IActionResult> GetAll()
    {
        return Ok(await universityClient.GetStudentGroupsAsync());
    }

    [HttpGet("my")]
    [Authorize]
    public async Task<IActionResult> GetMy()
    {
        var sub = User.FindFirst("sub")?.Value;
        if (sub is null)
            return Unauthorized();

        var groupId = await universityClient.GetStudentGroupIdAsync(sub);
        return Ok(new { groupId });
    }
}

namespace OmgtuPortal.University;

public interface IUniversityClient
{
    Task<IReadOnlyList<StudentGroup>> GetStudentGroupsAsync();
    Task<string?> GetStudentGroupIdAsync(string sub);
}

public record StudentGroup(string Id, string Name);

using System.Net.Http.Json;

namespace OmgtuPortal.University;

public class HttpUniversityClient(HttpClient httpClient) : IUniversityClient
{
    public async Task<IReadOnlyList<StudentGroup>> GetStudentGroupsAsync()
    {
        var groups = await httpClient.GetFromJsonAsync<List<StudentGroup>>("groups");
        return groups ?? [];
    }

    public async Task<string?> GetStudentGroupIdAsync(string sub)
    {
        var response = await httpClient.GetFromJsonAsync<GroupIdResponse>($"groups/{sub}");
        return response?.GroupId;
    }

    private record GroupIdResponse(string? GroupId);
}

namespace OmgtuPortal.University;

public class LocalUniversityClient : IUniversityClient
{
    private static readonly IReadOnlyList<StudentGroup> Groups =
    [
        new("1", "ИВТ-111"),
        new("2", "ИВТ-112"),
        new("3", "ИВТ-211"),
        new("4", "ПМИ-101"),
        new("5", "ПМИ-201"),
        new("6", "ИСТ-101"),
        new("7", "ИСТ-201"),
        new("8", "МАТ-101"),
    ];

    public Task<IReadOnlyList<StudentGroup>> GetStudentGroupsAsync() =>
        Task.FromResult(Groups);

    public Task<string?> GetStudentGroupIdAsync(string sub)
    {
        var hash = (uint)sub.GetHashCode(StringComparison.Ordinal);
        var index = (int)(hash % Groups.Count);
        return Task.FromResult<string?>(Groups[index].Id);
    }
}

using System.Text;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.EntityFrameworkCore;
using Microsoft.IdentityModel.Tokens;
using OmgtuPortal;
