using Polly;
using Polly.Extensions.Http;

// Load .env file
DotNetEnv.Env.Load();

var settings = AppSettings.Load();

// Validate required settings
var errors = new List<string>();
if (!settings.Autologin)
{
    if (string.IsNullOrWhiteSpace(settings.KeycloakAuthority))
        errors.Add("KEYCLOAK_AUTHORITY is required when AUTOLOGIN is not enabled");
    if (string.IsNullOrWhiteSpace(settings.KeycloakAudience))
        errors.Add("KEYCLOAK_AUDIENCE is required when AUTOLOGIN is not enabled");
}
else if (string.IsNullOrWhiteSpace(settings.AutologinKey))
{
    errors.Add("AUTOLOGIN_KEY is required when AUTOLOGIN is enabled");
}

if (errors.Count > 0)
{
    throw new InvalidOperationException(
        "Configuration errors:\n" + string.Join("\n", errors.Select(e => $"  - {e}")));
}

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton(settings);

// Configure Authentication
if (settings.Autologin)
{
    builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
        .AddJwtBearer(options =>
        {
            options.TokenValidationParameters = new TokenValidationParameters
            {
                ValidateIssuer = false,
                ValidateAudience = false,
                ValidateLifetime = false,
                ValidateIssuerSigningKey = true,
                IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(settings.AutologinKey))
            };
        });
}
else
{
    builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
        .AddJwtBearer(options =>
        {
            options.Authority = settings.KeycloakAuthority;
            options.Audience = settings.KeycloakAudience;
            options.RequireHttpsMetadata = false;

            options.TokenValidationParameters = new TokenValidationParameters
            {
                ValidateIssuer = true,
                ValidIssuer = settings.KeycloakAuthority,
                ValidateAudience = true,
                ValidAudience = settings.KeycloakAudience,
                ValidateLifetime = true,
                NameClaimType = "preferred_username",
                RoleClaimType = "role"
            };

            options.Events = new JwtBearerEvents
            {
                OnTokenValidated = context =>
                {
                    KeycloakClaimsMapper.MapRoles(context);
                    return Task.CompletedTask;
                }
            };
        });
}

// Configure Database
if (builder.Environment.IsDevelopment())
{
    var dbPath = Path.Combine(builder.Environment.ContentRootPath, "app.db");
    builder.Services.AddDbContext<AppDbContext>(options => options.UseSqlite($"Data Source={dbPath}"));
}
else
{
    var connectionString = Environment.GetEnvironmentVariable("DATABASE_URL")
                           ?? throw new InvalidOperationException("DATABASE_URL is required in production");
    builder.Services.AddDbContext<AppDbContext>(options => options.UseNpgsql(connectionString));
}

                }
            };
        });
}

// Configure Database
if (builder.Environment.IsDevelopment())
{
    var dbPath = Path.Combine(builder.Environment.ContentRootPath, "app.db");
    builder.Services.AddDbContext<AppDbContext>(options => options.UseSqlite($"Data Source={dbPath}"));
}
else
{
    var connectionString = Environment.GetEnvironmentVariable("DATABASE_URL")
                           ?? throw new InvalidOperationException("DATABASE_URL is required in production");
    builder.Services.AddDbContext<AppDbContext>(options => options.UseNpgsql(connectionString));
}

// Configure University Client
if (!string.IsNullOrWhiteSpace(settings.UniversityBaseUrl))
{
    builder.Services.AddHttpClient<IUniversityClient, HttpUniversityClient>(client =>
        {
            client.BaseAddress = new Uri(settings.UniversityBaseUrl);
            client.Timeout = TimeSpan.FromSeconds(10);
        })
        .AddTransientHttpErrorPolicy(p =>
            p.WaitAndRetryAsync(3, attempt => TimeSpan.FromMilliseconds(200 * Math.Pow(2, attempt))));
}
else if (builder.Environment.IsDevelopment())
{
    builder.Services.AddSingleton<IUniversityClient, LocalUniversityClient>();
}
else
{
    throw new InvalidOperationException(
        "UNIVERSITY_BASE_URL is required in production");
}

builder.Services.AddAuthorization();
builder.Services.AddControllers();

var app = builder.Build();

// AUTOLOGIN middleware: inject synthetic JWT for /api/* requests without Authorization header
if (settings.Autologin)
{
    app.Use(async (context, next) =>
    {
        if (context.Request.Path.StartsWithSegments("/api")
            && !context.Request.Headers.ContainsKey("Authorization"))
        {
            var token = AutologinTokenGenerator.Generate(settings.AutologinKey);
            context.Request.Headers.Append("Authorization", $"Bearer {token}");
        }

        await next();
    });
}

// Apply pending migrations on startup
using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
    db.Database.Migrate();
}

app.UseAuthentication();
app.UseAuthorization();

app.MapControllers();

// In production: serve Vue SPA from .frontend/dist
if (!app.Environment.IsDevelopment())
{
    var distPath = Path.Combine(app.Environment.ContentRootPath, ".frontend", "dist");

    var fileProvider = new Microsoft.Extensions.FileProviders.PhysicalFileProvider(distPath);

    app.UseStaticFiles(new StaticFileOptions
    {
        FileProvider = fileProvider,
        RequestPath = ""
    });

    app.MapFallback(context =>
    {
        // Don't fallback for /api/* routes
        if (context.Request.Path.StartsWithSegments("/api"))
        {
            context.Response.StatusCode = 404;
            return Task.CompletedTask;
        }

        context.Response.ContentType = "text/html";
        return context.Response.SendFileAsync(fileProvider.GetFileInfo("index.html"));
    });
}

app.Run();

namespace OmgtuPortal;

public class AppSettings
{
    public bool Autologin { get; init; }
    public string AutologinKey { get; init; } = "";
    public string KeycloakAuthority { get; init; } = "";
    public string KeycloakAudience { get; init; } = "";
    public string? UniversityBaseUrl { get; init; }

    public static AppSettings Load()
    {
        return new AppSettings
        {
            Autologin = Environment.GetEnvironmentVariable("AUTOLOGIN")
                ?.Equals("true", StringComparison.OrdinalIgnoreCase) ?? false,
            AutologinKey = Environment.GetEnvironmentVariable("AUTOLOGIN_KEY") ?? "",
            KeycloakAuthority = Environment.GetEnvironmentVariable("KEYCLOAK_AUTHORITY") ?? "",
            KeycloakAudience = Environment.GetEnvironmentVariable("KEYCLOAK_AUDIENCE") ?? "",
            UniversityBaseUrl = Environment.GetEnvironmentVariable("UNIVERSITY_BASE_URL"),
        };
    }
}

