public class LocalUniversityClient : IUniversityClient
{
    private static readonly IReadOnlyList<StudentGroup> Groups =
    [
        new("1", "ИВТ-111"),
        new("2", "ИВТ-112"),
        new("3", "ИВТ-211"),
        new("4", "ПМИ-101"),
        new("5", "ПМИ-201"),
        new("6", "ИСТ-101"),
        new("7", "ИСТ-201"),
        new("8", "МАТ-101"),
    ];

    public Task<IReadOnlyList<StudentGroup>> GetStudentGroupsAsync() =>
        Task.FromResult(Groups);

    public Task<string?> GetStudentGroupIdAsync(string sub)
    {
        var hash = (uint)sub.GetHashCode(StringComparison.Ordinal);
        var index = (int)(hash % Groups.Count);
        return Task.FromResult<string?>(Groups[index].Id);
    }
}
