using System.Security.Claims;
using System.Text.Encodings.Web;
using System.Text.Json;
using dotenv.net;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.FileProviders;
using Microsoft.Extensions.Options;
using Microsoft.IdentityModel.Tokens;
using OmgtuPortal;
using OmgtuPortal.Data;
using OmgtuPortal.University;
using Scalar.AspNetCore;

DotEnv.Load();

var appSettings = AppSettings.FromEnvironment();

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton(appSettings);
builder.Services.AddOpenApi();

// Database
builder.Services.AddDbContext<AppDbContext>(options =>
{
    if (builder.Environment.IsDevelopment())
        options.UseSqlite("Data Source=app.db");
    else
        options.UseNpgsql(appSettings.DatabaseUrl);
});

// CORS
builder.Services.AddCors(options =>
{
    options.AddDefaultPolicy(policy =>
    {
        var origins = appSettings.CorsOrigins
            .Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);

        policy.WithOrigins(origins)
              .AllowAnyHeader()
              .AllowAnyMethod()
              .AllowCredentials();
    });
});

// Authentication
if (appSettings.AutoLogin && builder.Environment.IsDevelopment())
{
    builder.Services.AddAuthentication("DevAutoLogin")
        .AddScheme<AuthenticationSchemeOptions, DevAutoLoginHandler>("DevAutoLogin", null);
}
else
{
    builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
        .AddJwtBearer(options =>
        {
            options.Authority = appSettings.Authority;
            options.Audience = appSettings.KeycloakClientId;
            options.RequireHttpsMetadata = !builder.Environment.IsDevelopment();

            options.TokenValidationParameters = new TokenValidationParameters
            {
                ValidateIssuer = true,
                ValidIssuer = appSettings.Authority,
                ValidateAudience = true,
                ValidAudience = appSettings.KeycloakClientId,
                ValidateLifetime = true,
            };

            options.Events = new JwtBearerEvents
            {
                OnTokenValidated = context =>
                {
                    if (context.Principal?.Identity is not ClaimsIdentity identity)
                        return Task.CompletedTask;

                    var realmAccess = identity.FindFirst("realm_access")?.Value;
                    if (realmAccess is null)
                        return Task.CompletedTask;

                    try
                    {
                        using var doc = JsonDocument.Parse(realmAccess);
                        if (doc.RootElement.TryGetProperty("roles", out var roles))
                        {
                            foreach (var role in roles.EnumerateArray())
                            {
                                var value = role.GetString();
                                if (!string.IsNullOrEmpty(value))
                                    identity.AddClaim(new Claim(ClaimTypes.Role, value));
                            }
                        }
                    }
                    catch (JsonException)
                    {
                        // Ignore malformed claim
                    }

                    return Task.CompletedTask;
                }
            };
        });
}

builder.Services.AddAuthorization();
builder.Services.AddControllers();

// University client
switch (appSettings.UniversityProvider?.ToLowerInvariant())
{
    case "http":
        builder.Services.AddHttpClient<IUniversityClient, HttpUniversityClient>(client =>
        {
            client.BaseAddress = new Uri(appSettings.UniversityBaseUrl
                ?? throw new InvalidOperationException(
                    "UNIVERSITY_BASE_URL is required when UNIVERSITY_PROVIDER=http"));
            client.Timeout = TimeSpan.FromSeconds(10);
        });
        break;
    default:
        builder.Services.AddSingleton<IUniversityClient, LocalUniversityClient>();
        break;
}

